/**
 * Builds the sample rows for a cuisine. They carry no hearts: every count in
 * the cookbook is one somebody actually clicked.
 *
 * Their ids are negative on purpose: a generated recipe brings its own id from
 * the cookbook, and both lists end up in the same @for loop, where a duplicate
 * key would make Angular reuse the wrong row.
 */
export function recipesFor(cuisine: CuisineStyle): CuisineRecipe[] {
  return DEMO_TITLES[cuisine].map((entry, index) => ({
    id: -(index + 1),
    title: entry.title,
    tags: entry.tags,
    cookingTimeMinutes: entry.minutes,
    likes: 0,
  }));
}
